import crypto14 from "node:crypto";
var SECRET = crypto14.createHash("sha256").update(env.JWT_ACCESS_SECRET).digest();
function signBillToken(orderId) {
  const sig = crypto14.createHmac("sha256", SECRET).update(`bill:${orderId}`).digest("base64url").slice(0, 10);
  return `${orderId}.${sig}`;
}
function verifyBillToken(token2) {
  const dot = token2.indexOf(".");
  if (dot <= 0) return null;
  const idPart = token2.slice(0, dot);
  const sig = token2.slice(dot + 1);
  const orderId = Number(idPart);
  if (!Number.isSafeInteger(orderId) || orderId <= 0) return null;
  const expectedFull = crypto14.createHmac("sha256", SECRET).update(`bill:${orderId}`).digest("base64url");
  const expected = sig.length === 10 ? expectedFull.slice(0, 10) : expectedFull;
  const a = Buffer.from(sig);
  const b = Buffer.from(expected);
  if (a.length !== b.length) return null;
  try {
    if (!crypto14.timingSafeEqual(a, b)) return null;
  } catch {
    return null;
  }
  return { orderId };
}

// src/lib/lanIp.ts
import dgram from "node:dgram";
import os3 from "node:os";
function detectLanIp() {
  const candidates = ["192.168.1.1", "192.168.0.1", "10.0.0.1", "172.16.0.1", "8.8.8.8"];
  const fromInterfaces = () => {
    for (const ifaces of Object.values(os3.networkInterfaces())) {
      for (const iface of ifaces ?? []) {
        if (iface.family === "IPv4" && !iface.internal) return iface.address;
      }
    }
    return "192.168.1.100";
  };
  return new Promise((resolve4) => {
    let i = 0;
    const tryNext = () => {
      if (i >= candidates.length) {
        resolve4(fromInterfaces());
        return;
      }
      const target = candidates[i++];
      const sock = dgram.createSocket("udp4");
      const fail2 = () => {
        try {
          sock.close();
        } catch {
        }
        tryNext();
      };
      sock.on("error", fail2);
      sock.on("connect", () => {
        let ip = "";
        try {
          ip = sock.address().address;
          sock.close();
        } catch {
        }
        if (ip && !ip.startsWith("127.")) resolve4(ip);
        else tryNext();
      });
      try {
        sock.connect(80, target);
      } catch {
        fail2();
      }
    };
    tryNext();
  });
}

